const fs = require('fs')

module.exports = settings_sync

// keeps this device's settings (dconf + extensions) and the synced settings in step. synced.json remembers the value both sides agreed on last,
// so a change made on this device can be told apart from a change that came from another device
function settings_sync ({ local, store, rules, backup, file }) {
  const state = { synced: {} }
  const api = { load, push_local_changes, diff, apply, rollback }
  return api

  async function load () { state.synced = (await read_json(file)) || {} }

  // sends what changed on this device since the last sync, returns the sent keys
  async function push_local_changes () {
    const here = await local.read_all()
    const remote = await store.read_all()
    const keys = new Set([...Object.keys(here), ...Object.keys(state.synced), ...Object.keys(remote)])
    const pushed = []
    for (const key of keys) {
      const value = here[key] ?? null
      if (!rules.is_synced(key, value)) continue
      if (value === (remote[key]?.value ?? null)) state.synced[key] = value // both sides agree
      else if (is_changed_here({ key, value, remote, synced: state.synced })) pushed.push(key)
    }
    const sendable = []
    const errors = []
    for (const key of pushed) await local.prepare(key, here[key] ?? null).then(() => sendable.push(key), err => errors.push(`${key}: ${err.message}`))
    for (const key of sendable) await store.set(key, here[key] ?? null)
    for (const key of sendable) state.synced[key] = here[key] ?? null
    await save()
    if (errors.length) throw new Error('could not share ' + errors.join(', ')) // the rest was sent
    return sendable
  }

  // what the other devices changed and this device does not have yet: [{ key, local, remote }]
  async function diff () {
    const here = await local.read_all()
    const remote = await store.read_all()
    const changes = []
    for (const key in remote) {
      const value = remote[key].value
      const current = here[key] ?? null
      if (!rules.is_synced(key, value) || value === current) continue
      if (key in state.synced && value === state.synced[key]) continue // the change is on this side, push sends it
      changes.push({ key, local: current, remote: value })
    }
    return changes
  }

  // backs up, then writes the changes here. one failing change (like an extension that does not fit) does not stop the rest
  async function apply (changes) {
    if (!changes.length) return { id: null, failed: [] }
    const id = await backup.save(changes)
    const failed = []
    for (const change of changes) await local.write(change.key, change.remote).catch(err => failed.push({ ...change, error: err.message }))
    for (const change of changes) if (!failed.some(f => f.key === change.key)) state.synced[change.key] = change.remote // so an edit right after counts as a change here
    await save()
    return { id, failed }
  }

  // puts back a backup on this device only, the remote values show up in diff again
  async function rollback (id) {
    const changes = await backup.rollback(id)
    for (const change of changes) state.synced[change.key] = change.local
    await save()
    return changes
  }

  function save () { return fs.promises.writeFile(file, JSON.stringify(state.synced, null, 2)) }
}

/***************************************
HELPERS
***************************************/
// a key never synced before that the others already have is not a change here: the others win on the first sync
function is_changed_here ({ key, value, remote, synced }) {
  if (key in synced) return value !== synced[key]
  return !(key in remote)
}

function read_json (file) { return fs.promises.readFile(file, 'utf8').then(JSON.parse).catch(() => null) }
